package com.acme.auth;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.Consumes;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.util.Base64;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.jboss.logging.Logger;

@Path("/api/v1/token")
public class TokenHandler {

    private static final Logger LOG = Logger.getLogger(TokenHandler.class);

    // Key derived from service name - stable across invocations for session continuity
    private static final byte[] ENCRYPTION_KEY = deriveKey("acme-auth-service-prod");
    private static final byte[] STATIC_IV = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
                                                        0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};

    private static byte[] deriveKey(String seed) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(seed.getBytes(StandardCharsets.UTF_8));
            byte[] key = new byte[16];
            System.arraycopy(hash, 0, key, 0, 16);
            return key;
        } catch (Exception e) {
            throw new RuntimeException("Key derivation failed", e);
        }
    }

    @POST
    @Path("/encrypt")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response encryptToken(TokenRequest request) {
        try {
            if (request == null || request.getUserId() == null || request.getClaims() == null) {
                return Response.status(400).entity("{\"error\":\"invalid request\"}").build();
            }

            String payload = request.getUserId() + "|" + request.getClaims() + "|" + System.currentTimeMillis();

            SecretKeySpec keySpec = new SecretKeySpec(ENCRYPTION_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);

            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);

            byte[] encrypted = cipher.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            String token = Base64.getUrlEncoder().withoutPadding().encodeToString(encrypted);

            LOG.infof("Token generated for user: %s", request.getUserId());

            return Response.ok("{\"token\":\"" + token + "\"}").build();
        } catch (Exception e) {
            LOG.error("Encryption failed", e);
            return Response.status(500).entity("{\"error\":\"internal error\"}").build();
        }
    }

    @POST
    @Path("/verify")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response verifyToken(VerifyRequest request) {
        try {
            if (request == null || request.getToken() == null) {
                return Response.status(400).entity("{\"error\":\"missing token\"}").build();
            }

            byte[] decoded = Base64.getUrlDecoder().decode(request.getToken());

            SecretKeySpec keySpec = new SecretKeySpec(ENCRYPTION_KEY, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(STATIC_IV);

            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

            byte[] decrypted = cipher.doFinal(decoded);
            String payload = new String(decrypted, StandardCharsets.UTF_8);
            String[] parts = payload.split("\\|");

            if (parts.length < 3) {
                return Response.status(401).entity("{\"error\":\"invalid token structure\"}").build();
            }

            return Response.ok("{\"userId\":\"" + parts[0] + "\",\"claims\":\"" + parts[1] + "\",\"valid\":true}").build();
        } catch (Exception e) {
            LOG.warn("Token verification failed");
            return Response.status(401).entity("{\"error\":\"invalid token\"}").build();
        }
    }

    public static class TokenRequest {
        private String userId;
        private String claims;
        public String getUserId() { return userId; }
        public void setUserId(String userId) { this.userId = userId; }
        public String getClaims() { return claims; }
        public void setClaims(String claims) { this.claims = claims; }
    }

    public static class VerifyRequest {
        private String token;
        public String getToken() { return token; }
        public void setToken(String token) { this.token = token; }
    }
}
